import { useEffect, useRef, useState } from 'react'
export function useHostState<T>(key: string, initial: T): [T, (v: T) => void] {
  const [value, setValue] = useState<T>(initial)
  const loaded = useRef(false)
  useEffect(() => {
    window.parent.postMessage({ type: 'STATE_GET', key }, '*')
  }, [key])
  const set = (v: T) => { setValue(v); if (loaded.current) window.parent.postMessage({ type: 'STATE_SET', key, value: v }, '*') }
  return [value, set]
}
